  ('#59', 'Stepping Stone Cafe', '2-20 Malt Dr, Long Island City, NY 11101', 'Queens', '11101', 40.73831, -73.95831, 'Visit Completed', 'Iris', 'markers.csv', 'Stepping Stone Cafe acts as the perfect launching pad for your workday, offering a friendly and unpretentious environment. The cozy layout features dependable seating and a welcoming neighborhood crowd that makes it easy to settle in. Enjoy a solid cup of coffee and a pastry while knocking out your to-do list.', TRUE, FALSE, TRUE, TRUE, TRUE, 'Many', FALSE, 'NO', 'Denisse'),
  ('#60', 'The Local Bar & Cafe', '13-02 44th Ave, Long Island City, NY 11101', 'Queens', '11101', 40.744687, -73.955717, 'Assigned', 'Denisse', 'markers.csv', 'A great hangout cafe/bar to get work done and/or socialize, closes for the night for hotel members only later in the evening.', TRUE, TRUE, TRUE, FALSE, TRUE, 'Ample', TRUE, 'Before evening', 'Denisse'),
  ('#61', 'Olive Coffee', '30-04 30th St, Astoria, NY 11102', 'Queens', '11102', 40.768525, -73.938467, 'Assigned', 'Denisse', 'markers.csv', 'Gold Coffee is a sleek and inviting neighborhood spot that delivers high-quality brews in a polished setting. It features a clean, minimalist aesthetic with comfortable seating areas tailored for focused laptop sessions. Friendly baristas and a steady stream of delicious espresso drinks make it a reliable daytime workspace.', TRUE, TRUE, TRUE, FALSE, TRUE, 'Some', TRUE, 'YES', 'Denisse'),
  ('#62', 'Full Moon Cafe', '42-14 Greenpoint Ave, Sunnyside, NY 11104', 'Queens', '11104', 40.74067, -73.92253, 'Incomplete', 'Sayraliz', 'markers.csv', 'Full Moon Cafe is a cozy neighborhood spot that charms locals with its unpretentious atmosphere and friendly service. The relaxed environment offers a comfortable backdrop for tackling daily tasks without the rush of corporate coffee chains. Patrons can enjoy reliable brews and classic cafe bites in a laid-back setting.', TRUE, TRUE, TRUE, TRUE, TRUE, 'Ample', FALSE, 'NO', 'Sayraliz'),
  ('#63', 'Busy Bee Coffee', '35-20 Leavitt St, Flushing, NY 11354', 'Queens', '11354', 40.76439, -73.82888, 'Assigned', 'Denisse', 'markers.csv', 'Busy Bee Coffee lives up to its name by offering an energetic, bustling environment that keeps productivity flowing. The cheerful interior is well-suited for fast-paced remote work sessions or quick morning pit stops. With a menu full of revitalizing espresso drinks and quick bites, it keeps momentum high.', TRUE, TRUE, TRUE, TRUE, TRUE, 'Ample', FALSE, 'NO', 'Denisse'),
  ('#64', 'Florist Bar Co', '135-18 Northern Blvd, Flushing, NY 11354', 'Queens', '11354', 40.76254, -73.832558, 'Assigned', 'Denisse', 'markers.csv', 'Florist Bar Co. is one of the most unique cafes to have scouted, hidden away in flushing with a projector screen often showing animal crossing or fun displays, tons of comfortable seats and outlets spread out throughout the cafe, not too much walking space but tons of seats, beautiful flowers and fun drinks. Only downside is WiFi has a limit of 2 hours with each purchase to help upkeep their business tucked away here in Flushing but is an easy fix.', TRUE, TRUE, TRUE, TRUE, TRUE, 'Ample', TRUE, 'No After 7PM', 'Denisse'),
  ('#65', 'Good Days Cafe', '68-01 Fresh Pond Rd, Ridgewood, NY 11385', 'Queens', '11385', 40.70517, -73.89629, 'Assigned', 'Denisse', 'markers.csv', 'Good Days Cafe radiates positivity with its bright decor, uplifting playlist, and welcoming neighborhood energy. The thoughtfully curated interior features comfortable corners that invite guests to settle in for a productive afternoon. It''s a delightful spot designed to turn any routine workday around.', TRUE, TRUE, TRUE, TRUE, FALSE, 'Ample', FALSE, 'NO', 'Denisse'),
